def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full colored rows encode a repeating sequence of horizontal bands.
    rows = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] != 0 and all(x == row[0] for x in row)]
    if rows:
        n = len(rows)
        pattern = {r % n: color for r, color in rows}
        return [[pattern[r % n] for _ in range(w)] for r in range(h)]

    # Diagonal tracks encode a repeating pattern along down-right diagonals.
    tracks = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color != 0:
                tracks.setdefault(c - r, []).append(color)

    tracks = {d: colors for d, colors in tracks.items() if len(colors) >= 2}
    n = len(tracks)
    pattern = {d % n: colors[0] for d, colors in tracks.items()}
    return [[pattern[(c - r) % n] for c in range(w)] for r in range(h)]

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full colored rows encode a repeating vertical sequence.
    rows = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] != 0 and all(x == row[0] for x in row)]
    if rows:
        n = len(rows)
        pattern = {r % n: color for r, color in rows}
        return [[pattern[r % n] for _ in range(w)] for r in range(h)]

    # Otherwise, infer which diagonal direction contains the encoded tracks.
    groups = []
    for key_fn in (lambda r, c: c - r, lambda r, c: r + c):
        tracks = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    tracks.setdefault(key_fn(r, c), []).append(color)
        score = sum(len(colors) * (len(colors) - 1) // 2
                    for colors in tracks.values())
        groups.append((score, tracks, key_fn))

    _, tracks, key_fn = max(groups, key=lambda item: item[0])
    n = len(tracks)

    # Track positions modulo the number of encoded tracks define the tiling.
    votes = {}
    for key, colors in tracks.items():
        residue = key % n
        counts = {}
        for color in colors:
            counts[color] = counts.get(color, 0) + 1
        color = max(counts, key=counts.get)
        votes.setdefault(residue, {})
        votes[residue][color] = votes[residue].get(color, 0) + 1

    pattern = {residue: max(counts, key=counts.get)
               for residue, counts in votes.items()}
    return [[pattern[key_fn(r, c) % n] for c in range(w)]
            for r in range(h)]

def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    ids = {p: i for i, p in enumerate(cells)}
    full = (1 << len(cells)) - 1

    # Tile the shape with solid 2x2 squares and the three L patterns
    # observed in the demonstrations.
    pieces = []
    patterns = [
        (((0, 1), (1, 0), (1, 1)), 2),  # missing top-left
        (((0, 0), (0, 1), (1, 1)), 3),  # missing bottom-left
        (((0, 0), (1, 0), (1, 1)), 4),  # missing top-right
    ]
    for r in range(h - 1):
        for c in range(w - 1):
            square = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            if all(p in ids for p in square):
                mask = sum(1 << ids[p] for p in square)
                pieces.append((mask, 1, r, c))

            for offsets, color in patterns:
                shape = [(r + dr, c + dc) for dr, dc in offsets]
                other = [p for p in square if p not in shape]
                if all(p in ids for p in shape) and all(p not in ids for p in other):
                    mask = sum(1 << ids[p] for p in shape)
                    pieces.append((mask, color, r, c))

    by_cell = [[] for _ in cells]
    for piece in pieces:
        mask, color, r, c = piece
        for i in range(len(cells)):
            if mask >> i & 1:
                by_cell[i].append(piece)
    for options in by_cell:
        options.sort(key=lambda p: (0 if p[1] == 1 else 1, p[2], p[3], p[1]))

    failed = set()

    def search(rem):
        if rem == 0:
            return ()
        if rem in failed:
            return None
        i = (rem & -rem).bit_length() - 1
        for mask, color, r, c in by_cell[i]:
            if mask & rem == mask:
                result = search(rem ^ mask)
                if result is not None:
                    return ((mask, color),) + result
        failed.add(rem)
        return None

    tiling = search(full)
    out = [[0] * w for _ in range(h)]
    if tiling is None:
        for r, c in cells:
            out[r][c] = 1
        return out

    for mask, color in tiling:
        for i, (r, c) in enumerate(cells):
            if mask >> i & 1:
                out[r][c] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the solid divider and split into corresponding panels.
    if any(len(set(row)) == 1 for row in grid):
        d = next(r for r, row in enumerate(grid) if len(set(row)) == 1)
        a, b = grid[:d], grid[d + 1:]
        shared = set(v for row in a for v in row) & set(v for row in b for v in row)
        background = next(iter(shared))
        return [
            [3 if a[r][c] == b[r][c] else background for c in range(w)]
            for r in range(len(a))
        ]
    else:
        d = next(c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h)))
        a = [row[:d] for row in grid]
        b = [row[d + 1:] for row in grid]
        shared = set(v for row in a for v in row) & set(v for row in b for v in row)
        background = next(iter(shared))
        return [
            [3 if a[r][c] == b[r][c] else background for c in range(d)]
            for r in range(h)
        ]

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    by_color = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                by_color.setdefault(grid[r][c], []).append((r, c))

    # The largest object is the complete shape to reproduce.
    ref_color = max(by_color, key=lambda color: len(by_color[color]))
    ref = by_color[ref_color]
    r0 = min(r for r, c in ref)
    c0 = min(c for r, c in ref)
    base = {(r - r0, c - c0) for r, c in ref}

    def normalize(points):
        mr = min(r for r, c in points)
        mc = min(c for r, c in points)
        return frozenset((r - mr, c - mc) for r, c in points)

    # Include rotations and reflections so partial copies may be oriented differently.
    variants = []
    cur = set(base)
    for _ in range(4):
        variants.append(normalize(cur))
        cur = {(c, -r) for r, c in cur}
    cur = {(r, -c) for r, c in base}
    for _ in range(4):
        variants.append(normalize(cur))
        cur = {(c, -r) for r, c in cur}

    # Remove duplicate orientations while retaining their priority.
    variants = list(dict.fromkeys(variants))

    for color, cells in by_color.items():
        if color == ref_color:
            continue

        placed = False
        for shape in variants:
            ph = max(r for r, c in shape) + 1
            pw = max(c for r, c in shape) + 1
            first_r, first_c = cells[0]
            anchors = set()

            for sr, sc in shape:
                ar, ac = first_r - sr, first_c - sc
                if not (0 <= ar and 0 <= ac and ar + ph <= h and ac + pw <= w):
                    continue
                if all((r - ar, c - ac) in shape for r, c in cells):
                    anchors.add((ar, ac))

            if anchors:
                ar, ac = max(anchors)
                for dr, dc in shape:
                    out[ar + dr][ac + dc] = color
                placed = True
                break

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    edge_counts = Counter()
    for c in range(w):
        if grid[0][c] != bg:
            edge_counts[grid[0][c]] += 1
        if grid[h - 1][c] != bg:
            edge_counts[grid[h - 1][c]] += 1
    for r in range(h):
        if grid[r][0] != bg:
            edge_counts[grid[r][0]] += 1
        if grid[r][w - 1] != bg:
            edge_counts[grid[r][w - 1]] += 1

    marker = edge_counts.most_common(1)[0][0]

    seeds = [
        (r, c)
        for r in range(h)
        for c in range(w)
        if grid[r][c] != bg and grid[r][c] != marker
    ]
    seed_set = set(seeds)
    seed_colors = Counter(grid[r][c] for r, c in seeds)
    ray_color = seed_colors.most_common(1)[0][0] if seed_colors else marker
    k = len(seeds)

    out = [row[:] for row in grid]

    top = [c for c in range(w) if grid[0][c] == marker]
    bottom = [c for c in range(w) if grid[h - 1][c] == marker]
    left = [r for r in range(h) if grid[r][0] == marker]
    right = [r for r in range(h) if grid[r][w - 1] == marker]

    horizontal_score = len(top) + len(bottom)
    vertical_score = len(left) + len(right)

    def cast_horizontal(edge_row, positions, direction):
        for c in positions[-k:]:
            r = edge_row + direction
            while 0 <= r < h:
                if grid[r][c] == marker:
                    break
                if (r, c) in seed_set:
                    out[r][c] = 4
                    break
                out[r][c] = ray_color
                r += direction

    def cast_vertical(edge_col, positions, direction):
        for r0 in positions[-k:]:
            c = edge_col + direction
            while 0 <= c < w:
                if grid[r0][c] == marker:
                    break
                if (r0, c) in seed_set:
                    out[r0][c] = 4
                    break
                out[r0][c] = ray_color
                c += direction

    if horizontal_score >= vertical_score:
        if top:
            cast_horizontal(0, top, 1)
        if bottom:
            cast_horizontal(h - 1, bottom, -1)
    else:
        if left:
            cast_vertical(0, left, 1)
        if right:
            cast_vertical(w - 1, right, -1)

    for r, c in seeds:
        out[r][c] = 4

    return out

def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    edge = Counter()
    for c in range(w):
