def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(length, separators):
        result = []
        start = 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < length:
            result.append((start, length))
        return result

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)

    cells = [
        grid[r][c]
        for r0, r1 in row_spans
        for c0, c1 in col_spans
        for r in range(r0, r1)
        for c in range(c0, c1)
    ]
    background = Counter(cells).most_common(1)[0][0]

    panels = []
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            filled = sum(value != background for row in panel for value in row)
            panels.append((filled, r0, r1, c0, c1, panel))

    template = max(panels, key=lambda item: item[0])[5]
    out = [row[:] for row in grid]
    for _, r0, r1, c0, c1, _ in panels:
        for i, row in enumerate(template):
            out[r0 + i][c0:c1] = row[:]
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    outside = set()
    q = deque()

    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and
                    grid[nr][nc] == background and (nr, nc) not in outside):
                outside.add((nr, nc))
                q.append((nr, nc))

    out = [row[:] for row in grid]
    visited = set(outside)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in visited:
                continue
            component = []
            q = deque([(r, c)])
            visited.add((r, c))
            while q:
                cr, cc = q.popleft()
                component.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] == background and (nr, nc) not in visited):
                        visited.add((nr, nc))
                        q.append((nr, nc))
            fill = 7 if len(component) % 2 else 2
            for cr, cc in component:
                out[cr][cc] = fill

    return out

